<?php
require dirname(__DIR__).'/backend/app/bootstrap.php';$user=require_permission('create_tickets');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();try{
        $subject=input('subject',255);$issue=input('issue',20000);$category=input('category',80);$priority=input('priority',20);$department=positive_id($_POST,'department_id');$assignee=positive_id($_POST,'assignee_id');$staffId=positive_id($_POST,'staff_id');
        if($subject==='' || $issue==='')throw new InvalidArgumentException('Subject and issue details are required.');
        $category=input('category_manual',80)?:$category;
        $employeeManual=input('employee_manual',150);$departmentManual=input('department_manual',120);$assigneeManual=input('assignee_manual',150);
        if($category==='' || !isset(TICKET_PRIORITIES[$priority]))throw new InvalidArgumentException('Select a valid category and priority.');
        if($departmentManual==='' && !in_array($department,array_map('intval',array_column(active_departments(),'id')),true))throw new InvalidArgumentException('Select a department or type a department name.');
        if($assigneeManual!=='')$assignee=0;
        if($assignee && !in_array($assignee,array_map('intval',array_column(active_users(),'id')),true))throw new InvalidArgumentException('Select an active assignee.');
        $employee=$staffId?query('SELECT full_name FROM staff_directory WHERE id=?',[$staffId])->fetchColumn():false;
        if($employeeManual!==''){$employee=$employeeManual;$staffId=0;}
        if(!$employee)throw new InvalidArgumentException('Select an employee or type an employee name.');
        $uploads=ticket_uploads();
        db()->beginTransaction();
        if($departmentManual!==''){
            query('INSERT INTO departments(name,code) VALUES(?,?) ON DUPLICATE KEY UPDATE name=VALUES(name)',[$departmentManual,'manual-'.bin2hex(random_bytes(12))]);
            $department=(int)query('SELECT id FROM departments WHERE name=?',[$departmentManual])->fetchColumn();
        }
        query('INSERT INTO tickets(ticket_number,issue_escalator,subject,category,department_id,employee_name,description,issue,priority,assignee_id,created_by,staff_id,manual_assignee_name) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',['WTS-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3))),$user['full_name'],$subject,$category,$department,$employee,$issue,$issue,$priority,$assignee?:null,$user['id'],$staffId?:null,$assigneeManual?:null]);
        $id=(int)db()->lastInsertId();if($assignee)sync_ticket_assignees($id,[$assignee]);sync_ticket_departments($id,[$department]);activity($id,(int)$user['id'],'created',['subject'=>$subject,'priority'=>$priority]);save_ticket_uploads($id,(int)$user['id'],$uploads);db()->commit();flash('Ticket created.');redirect('ticket.php?id='.$id);
    }catch(InvalidArgumentException $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
$categoryNames=array_values(array_unique(array_merge(array_keys(TICKET_CATEGORIES),array_column(query('SELECT DISTINCT category FROM tickets ORDER BY category')->fetchAll(),'category'))));
$v=fn($key,$default='')=>$_SERVER['REQUEST_METHOD']==='POST'?request_string($_POST,$key):$default;
page_start('Create ticket',$user);?><a class="back-link" href="index.php">&larr; Tickets</a><section class="panel"><h2>What needs attention?</h2><p class="muted">Choose from the lists or type a value below them. Typed values take precedence.</p><?php error_notice($error);?><form method="post" enctype="multipart/form-data"><?php csrf_field();?><div class="form-grid"><label class="wide">Subject *<input name="subject" maxlength="255" required value="<?=e($v('subject'))?>"></label><label>Employee *<select name="staff_id"><option value="">Select employee</option><?php options(query("SELECT id,CONCAT(full_name,'  ·  ',employee_code) name FROM staff_directory ORDER BY full_name")->fetchAll(),$v('staff_id',request_string($_GET,'staff_id')));?></select><input name="employee_manual" maxlength="150" placeholder="Or type employee name" value="<?=e($v('employee_manual'))?>"><small>Choose an employee or enter a name.</small></label><label>Department *<select name="department_id"><option value="">Select department</option><?php options(active_departments(),$v('department_id'));?></select><input name="department_manual" maxlength="120" placeholder="Or type a new department" value="<?=e($v('department_manual'))?>"><small>A new department is saved for future selection.</small></label><label>Category *<select name="category" required><?php enum_options(array_combine($categoryNames,$categoryNames),$v('category'));?></select><input name="category_manual" maxlength="80" placeholder="Or type a category" value="<?=e($v('category_manual'))?>"></label><label>Priority *<select name="priority" required><?php enum_options(TICKET_PRIORITIES,$v('priority','normal'));?></select></label><label class="wide">Assigned to<select name="assignee_id"><option value="">Unassigned</option><?php options(active_users(),$v('assignee_id'),'full_name');?></select><input name="assignee_manual" maxlength="150" placeholder="Or type assignee name" value="<?=e($v('assignee_manual'))?>"><small>A typed name overrides the selection and does not create a user account.</small></label><label class="wide">Issue details *<textarea name="issue" rows="7" maxlength="20000" required><?=e($v('issue'))?></textarea></label><label class="wide">Attachments (optional)<input type="file" name="attachments[]" multiple accept=".pdf,.txt,.csv,.jpg,.jpeg,.png,.webp,.docx,.xlsx"><small>Up to 3 files, 2 MB each. PDF, text, CSV, images, DOCX or XLSX. Select files again if validation fails.</small></label></div><div class="form-footer"><button class="button">Create ticket</button><a class="button button-secondary" href="index.php">Cancel</a></div></form></section><?php page_end();
